3869	/// This represents the state necessary to render a scrollbar for this
3947	fn viewportRowOffset(self: *PageList) usize {
3948	    return switch (self.viewport) {
3949	        .top => 0,
3950	        .active => self.total_rows - self.rows,
3951	        .pin => pin: {
3952	            // We assert integrity on this code path because it verifies
3953	            // that the cached value is correct.
3954	            defer self.assertIntegrity();
3955	
3956	            // Return cached value if available
3957	            if (self.viewport_pin_row_offset) |cached| break :pin cached;
3958	
3959	            // Traverse from the end and count rows until we reach the
3960	            // viewport pin. We count backwards because most of the time
3961	            // a user is scrolling near the active area.
3962	            const top_offset: usize = offset: {
3963	                var offset: usize = 0;
3964	                var node = self.pages.last;
3965	                while (node) |n| : (node = n.prev) {
3966	                    offset += n.rows();
3967	                    if (n == self.viewport_pin.node) {
3968	                        assert(n.rows() > self.viewport_pin.y);
3969	                        offset -= self.viewport_pin.y;
3970	                        break :offset self.total_rows - offset;
3971	                    }
3972	                }
3973	
3974	                // Invalid pins are not possible.
3975	                unreachable;
3976	            };
3977	
3978	            // The offset is from the bottom and our cached value and this
3979	            // function returns from the top, so we need to invert it.
3980	            self.viewport_pin_row_offset = top_offset;
3981	            break :pin top_offset;
3982	        },
3983	    };
3984	}
