5098	/// Create a new page node. This does not add it to the list and this
5099	/// does not do any memory size accounting with max_size/page_size.
5100	inline fn createPage(
5101	    self: *PageList,
5102	    opts: CreatePage,
5103	) Allocator.Error!*List.Node {
5104	    // log.debug("create page cap={}", .{opts.cap});
5105	
5106	    // If we have a node available for recycling (only during reflow,
5107	    // see recycle_node), reuse it directly rather than going through
5108	    // the memory pool.
5109	    if (self.recycle_node) |node| recycle: {
5110	        // Only a standard pool-owned resident node can be rebuilt
5111	        // in place for a standard-size layout.
5112	        if (opts.exact_size) break :recycle;
5113	        if (node.owned != .pool) break :recycle;
5114	        if (node.data != .resident) break :recycle;
5115	        const layout = Page.layout(opts.cap);
5116	        if (layout.total_size > std_size) break :recycle;
5117	
5118	        self.recycle_node = null;
5119	
5120	        // The pool guarantees that buffers it hands out are zeroed.
5121	        // A pool-owned page dirties only its Page.memory prefix of
5122	        // the underlying standard-size item, so zeroing that prefix
5123	        // re-establishes the guarantee (this mirrors destroyNodeExt,
5124	        // minus the decommit).
5125	        const page = &node.data.resident;
5126	        const item: *align(std.heap.page_size_min) [std_size]u8 =
5127	            @ptrCast(@alignCast(page.memory.ptr));
5128	        @memset(page.memory, 0);
5129	
5130	        // Accounting: a pool-owned node always accounts for a full
5131	        // pool item in page_size, so destroying the node and
5132	        // creating a new pooled one is a net zero.
5133	
5134	        node.* = .{
5135	            .data = .{ .resident = .initBuf(.init(item), layout) },
5136	            .serial = self.page_serial,
5137	            .owned = .pool,
5138	        };
5139	        node.page().size.rows = 0;
5140	        self.page_serial += 1;
5141	        return node;
5142	    }
5143	
5144	    return try createPageExt(
5145	        &self.pool,
5146	        opts,
5147	        &self.page_serial,
5148	        &self.page_size,
5149	    );
5150	}
