5152	inline fn createPageExt(
5153	    pool: *MemoryPool,
5154	    opts: CreatePage,
5155	    serial: *u64,
5156	    total_size: ?*usize,
5157	) Allocator.Error!*List.Node {
5158	    var page = try pool.nodes.create();
5159	    errdefer pool.nodes.destroy(page);
5160	
5161	    const layout = Page.layout(opts.cap);
5162	    const pooled = !opts.exact_size and layout.total_size <= std_size;
5163	    const page_alloc = pool.pages.allocator;
5164	
5165	    // It would be better to encode this into the Zig error handling
5166	    // system but that is a big undertaking and we only have a few
5167	    // centralized call sites so it is handled on its own currently.
5168	    assert(layout.total_size <= size.max_page_size);
5169	
5170	    // Our page buffer comes from our standard memory pool if it
5171	    // is within our standard size since this is what the pool
5172	    // dispenses. Otherwise, we use the heap allocator to allocate.
5173	    const page_buf = if (pooled) buf: {
5174	        const buf = try pool.pages.create();
5175	        terminal_mem.recommit(buf);
5176	        break :buf buf;
5177	    } else try page_alloc.alignedAlloc(
5178	        u8,
5179	        .fromByteUnits(std.heap.page_size_min),
5180	        layout.total_size,
5181	    );
