5183	        pool.pages.destroy(page_buf)
5184	    else
5185	        page_alloc.free(page_buf);
5186	
5187	    // In runtime safety modes, allocators fill with 0xAA. On freestanding
5188	    // (WASM), the WasmAllocator reuses freed slots without zeroing.
5189	    //
5190	    // Otherwise, we rely on pool item buffers being zeroed: fresh items
5191	    // come from the OS page allocator (zeroed pages), destroyNodeExt
5192	    // zeroes buffers before returning them to the pool, and the pool
5193	    // never writes into its items (see PagePool).
5194	    if (comptime std.debug.runtime_safety or builtin.target.os.tag == .freestanding)
5195	        @memset(page_buf, 0);
5196	
5197	    page.* = .{
5198	        .data = .{ .resident = .initBuf(.init(page_buf), layout) },
5199	        .serial = serial.*,
5200	        .owned = if (pooled) .pool else .heap,
5201	    };
5202	    page.page().size.rows = 0;
5203	    serial.* += 1;
5204	
5205	    if (total_size) |v| {
5206	        // Accumulate page size now. We don't assert or check max size
5207	        // because we may exceed it here temporarily as we are allocating
5208	        // pages before destroy.
5209	        v.* += page_buf.len;
5210	    }
5211	
5212	    return page;
5213	}
