  2666	        // If we are at the top, then we are done.
  2667	        if (self.screens.active.cursor.y == top) {
  2668	            if (wrap_mode != .reverse_extended) break;
  2669	
  2670	            self.screens.active.cursorAbsolute(right_margin, bottom);
  2671	            count -= 1;
  2672	            continue;
  2673	        }
  2674	
  2675	        // UNDEFINED TERMINAL BEHAVIOR. This situation is not handled in xterm
  2676	        // and currently results in a crash in xterm. Given no other known
  2677	        // terminal [to me] implements XTREVWRAP2, I decided to just mimic
  2678	        // the behavior of xterm up and not including the crash by wrapping
  2679	        // up to the (0, 0) and stopping there. My reasoning is that for an
  2680	        // appropriately sized value of "count" this is the behavior that xterm
  2681	        // would have. This is unit tested.
  2682	        if (self.screens.active.cursor.y == 0) {
  2683	            assert(self.screens.active.cursor.x == left_margin);
  2684	            break;
  2685	        }
  2686	
  2687	        // If our previous line is not wrapped then we are done.
  2688	        if (wrap_mode != .reverse_extended) {
  2689	            const prev_row = self.screens.active.cursorRowUp(1);
  2690	            if (!prev_row.wrap) break;
  2691	        }
  2692	
  2693	        self.screens.active.cursorAbsolute(right_margin, self.screens.active.cursor.y - 1);
  2694	        count -= 1;
  2695	    }
  2696	}
