  3323	/// Set Top and Bottom Margins If bottom is not specified, 0 or bigger than
  3324	/// the number of the bottom-most row, it is adjusted to the number of the
  3325	/// bottom most row.
  3326	///
  3327	/// If top < bottom set the top and bottom row of the scroll region according
  3328	/// to top and bottom and move the cursor to the top-left cell of the display
  3329	/// (when in cursor origin mode is set to the top-left cell of the scroll region).
  3330	///
  3331	/// Otherwise: Set the top and bottom row of the scroll region to the top-most
  3332	/// and bottom-most line of the screen.
  3333	///
  3334	/// Top and bottom are 1-indexed.
  3335	pub fn setTopAndBottomMargin(self: *Terminal, top_req: usize, bottom_req: usize) void {
  3336	    const top = @max(1, top_req);
  3337	    const bottom = @min(self.rows, if (bottom_req == 0) self.rows else bottom_req);
  3338	    if (top >= bottom) return;
  3339	
  3340	    self.scrolling_region.top = @intCast(top - 1);
  3341	    self.scrolling_region.bottom = @intCast(bottom - 1);
  3342	    self.setCursorPos(1, 1);
  3343	}
