  3345	/// DECSLRM
  3346	pub fn setLeftAndRightMargin(self: *Terminal, left_req: usize, right_req: usize) void {
  3347	    // We must have this mode enabled to do anything
  3348	    if (!self.modes.get(.enable_left_and_right_margin)) return;
  3349	
  3350	    const left = @max(1, left_req);
  3351	    const right = @min(self.cols, if (right_req == 0) self.cols else right_req);
  3352	    if (left >= right) return;
  3353	
  3354	    self.scrolling_region.left = @intCast(left - 1);
  3355	    self.scrolling_region.right = @intCast(right - 1);
  3356	    self.setCursorPos(1, 1);
  3357	}
