  3359	/// Scroll the text down by one row.
  3360	pub fn scrollDown(self: *Terminal, count: usize) void {
  3361	    // Preserve our x/y to restore.
  3362	    const old_x = self.screens.active.cursor.x;
  3363	    const old_y = self.screens.active.cursor.y;
  3364	    const old_wrap = self.screens.active.cursor.pending_wrap;
  3365	    defer {
  3366	        self.screens.active.cursorAbsolute(old_x, old_y);
  3367	        self.screens.active.cursor.pending_wrap = old_wrap;
  3368	    }
  3369	
  3370	    // If margins are set and kitty image placements exist, they need
  3371	    // adjusting around the scroll. Note this wraps scrollDown and NOT
  3372	    // insertLines: kitty scrolls images for SD/RI but leaves them
  3373	    // alone for IL/DL.
  3374	    var kitty_scroll: ?KittyScrollMargins = null;
  3375	    defer if (kitty_scroll) |*state| state.end();
  3376	    if (comptime build_options.kitty_graphics) {
  3377	        if (self.screens.active.kitty_images.placements.count() != 0) {
  3378	            @branchHint(.unlikely);
  3379	            const region_height: usize =
  3380	                @as(usize, self.scrolling_region.bottom - self.scrolling_region.top) + 1;
  3381	            kitty_scroll = self.kittyScrollMarginsBegin(
  3382	                @intCast(@min(count, region_height)),
  3383	                .in_place,
  3384	            );
  3385	        }
  3386	    }
  3387	
  3388	    // Move to the top of the scroll region
  3389	    self.screens.active.cursorAbsolute(self.scrolling_region.left, self.scrolling_region.top);
  3390	    self.insertLines(count);
  3391	}
